<template>
  <PageShell title="平台运营中心" description="统一维护客户租户、产品授权与平台服务运营">
    <template #actions><span class="platform-badge">PLATFORM ADMIN · 跨租户视图</span></template>

    <div class="platform-tabs">
      <button v-for="item in tabs" :key="item.key" :class="{ active: tab === item.key }" @click="switchTab(item.key)">{{ item.label }}</button>
    </div>
    <div v-if="notice" :class="['platform-notice', `platform-notice--${notice.type}`]">{{ notice.message }}</div>

    <div v-if="loading" class="platform-loading">正在加载平台数据…</div>

    <template v-else-if="tab === 'overview'">
      <div class="platform-kpis">
        <div v-for="item in overviewCards" :key="item.key" class="platform-kpi"><span>{{ item.label }}</span><b>{{ formatNumber(overview[item.key]) }}</b><small>{{ item.hint }}</small></div>
      </div>
      <div class="platform-overview-grid">
        <section class="platform-panel platform-intro"><p class="eyebrow">POLARIS PLATFORM</p><h2>平台运营总览</h2><p>平台租户拥有跨租户运营权限，所有授权、计费、积分和服务动作都会留下操作人和时间记录。</p><div class="platform-capabilities"><span v-for="item in capabilityCards" :key="item.label"><i>{{ item.icon }}</i><b>{{ item.label }}</b><small>{{ item.description }}</small></span></div></section>
        <section class="platform-panel"><div class="platform-panel-head"><div><h3>运营快捷入口</h3><p>从租户视角进入常用平台动作</p></div></div><div class="platform-actions-grid"><button v-for="item in quickActions" :key="item.key" @click="switchTab(item.key)"><span>{{ item.icon }}</span><b>{{ item.label }}</b><small>{{ item.description }}</small></button></div></section>
      </div>
    </template>

    <template v-else-if="tab === 'tenants'">
      <section class="platform-panel"><div class="platform-panel-head"><div><h3>客户租户</h3><p>创建、停用和维护客户工作区及套餐配置</p></div><div class="platform-head-actions"><input v-model="tenantKeyword" placeholder="搜索租户名称 / 编码" @keyup.enter="loadTenants" /><button class="button button-primary" @click="openTenantCreate">新增租户</button></div></div><DataTable :columns="tenantColumns" :rows="tenants" :loading="loading" :pagination="true" :page-size-options="[10, 20, 50]" export-name="platform-tenants"><template #cell-status="{ value }"><span class="status-pill" :class="value ? 'status-active' : 'status-inactive'">{{ value ? '已启用' : '已停用' }}</span></template><template #cell-traffic_remaining_bytes="{ value, row }"><span :class="Number(value) <= 0 ? 'text-danger' : ''">{{ trafficSize(value) }}</span><small class="traffic-cell-hint"> / {{ trafficSize(row.traffic_quota_bytes) }}</small></template><template #cell-storage_remaining_bytes="{ value, row }"><span :class="Number(value) <= 0 ? 'text-danger' : ''">{{ trafficSize(value) }}</span><small class="traffic-cell-hint"> / {{ trafficSize(row.storage_quota_bytes) }}</small></template><template #actions="{ row }"><div class="inline-actions"><button class="table-action" @click="openTenantEdit(row)">编辑</button><button class="table-action" @click="openFeature(row)">授权</button><button class="table-action" @click="openTraffic(row)">流量</button><button class="table-action" @click="openStorage(row)">存储</button><button class="table-action" @click="openBilling(row)">计费</button><button class="table-action" @click="openPoints(row)">积分</button></div></template></DataTable></section>
    </template>

    <template v-else-if="tab === 'features'">
      <section class="platform-panel"><div class="platform-panel-head"><div><h3>租户功能授权</h3><p>选择租户后配置产品模块、开放接口和增值能力</p></div><select v-model.number="selectedTenantId" @change="loadFeatureEditor"><option :value="0">请选择客户租户</option><option v-for="tenant in tenants" :key="tenant.id" :value="tenant.id">{{ tenant.tenant_name }} · {{ tenant.tenant_code }}</option></select></div><div v-if="selectedTenantId" class="feature-editor"><label v-for="feature in featureRows" :key="feature.feature_code" class="feature-option"><input v-model="selectedFeatureCodes" type="checkbox" :value="feature.feature_code" /><span><b>{{ feature.feature_name }}</b><small>{{ feature.feature_code }} · {{ feature.description }}</small></span><em>{{ feature.category }}</em></label><div class="feature-editor-foot"><span>已选择 {{ selectedFeatureCodes.length }} 项功能</span><button class="button button-primary" :disabled="saving" @click="saveFeatures">保存授权</button></div></div><div v-else class="platform-empty">请先选择一个客户租户</div></section>
    </template>

    <template v-else-if="tab === 'billing'">
      <section class="platform-panel"><div class="platform-panel-head"><div><h3>计费与账户</h3><p>查看账户余额、充值、消费和存储账单</p></div><select v-model.number="selectedTenantId" @change="loadBilling"><option :value="0">请选择客户租户</option><option v-for="tenant in tenants" :key="tenant.id" :value="tenant.id">{{ tenant.tenant_name }} · {{ tenant.tenant_code }}</option></select><button class="button button-primary" :disabled="!selectedTenantId" @click="openBillingModal">记一笔</button></div><div v-if="billing.account" class="account-summary"><div><span>账户余额</span><b>¥ {{ money(billing.account.balance) }}</b></div><div><span>累计收款</span><b>¥ {{ money(billing.account.total_paid) }}</b></div><div><span>累计消费</span><b>¥ {{ money(billing.account.total_consumed) }}</b></div></div><DataTable :columns="billingColumns" :rows="billing.records || []" :loading="loading" empty-text="暂无计费记录" /></section>
    </template>

    <template v-else-if="tab === 'points'">
      <section class="platform-panel"><div class="platform-panel-head"><div><h3>积分运营</h3><p>为客户租户发放或扣减平台积分，并保留流水</p></div><select v-model.number="selectedTenantId" @change="loadPoints"><option :value="0">请选择客户租户</option><option v-for="tenant in tenants" :key="tenant.id" :value="tenant.id">{{ tenant.tenant_name }} · {{ tenant.tenant_code }}</option></select><button class="button button-primary" :disabled="!selectedTenantId" @click="openPointsModal">调整积分</button></div><div v-if="points.account" class="account-summary points-summary"><div><span>当前余额</span><b>{{ formatNumber(points.account.balance) }}</b></div><div><span>累计发放</span><b>{{ formatNumber(points.account.total_earned) }}</b></div><div><span>累计消耗</span><b>{{ formatNumber(points.account.total_spent) }}</b></div></div><DataTable :columns="pointsColumns" :rows="points.ledger || []" :loading="loading" empty-text="暂无积分流水" /></section>
    </template>

    <template v-else-if="tab === 'traffic'">
      <section class="platform-panel"><div class="platform-panel-head"><div><h3>租户流量管理</h3><p>按真实请求与响应体字节数消耗，额度不足时接口直接返回 429 错误</p></div><select v-model.number="selectedTenantId" @change="loadTraffic"><option :value="0">请选择客户租户</option><option v-for="tenant in tenants" :key="tenant.id" :value="tenant.id">{{ tenant.tenant_name }} · {{ tenant.tenant_code }}</option></select><button class="button button-primary" :disabled="!selectedTenantId" @click="openTrafficModal">分配流量</button></div><div v-if="selectedTenantId && traffic.quota_bytes !== undefined" class="traffic-account"><div class="account-summary"><div><span>配额总量</span><b>{{ trafficSize(traffic.quota_bytes) }}</b></div><div><span>已使用</span><b>{{ trafficSize(traffic.used_bytes) }}</b></div><div><span>剩余流量</span><b :class="traffic.exhausted ? 'text-danger' : ''">{{ trafficSize(traffic.remaining_bytes) }}</b></div></div><div class="traffic-progress"><div><span>使用进度</span><b>{{ percentage(traffic.used_percent) }}%</b></div><div class="progress"><i :class="{ danger: traffic.exhausted, warning: traffic.low_balance }" :style="{ width: `${Math.min(100, Number(traffic.used_percent || 0))}%` }"></i></div><small>{{ traffic.exhausted ? '流量已用尽，租户请求将被拦截' : `剩余低于 ${traffic.warning_threshold_percent}% 时提醒` }}</small></div></div><div v-else class="platform-empty">请先选择一个客户租户</div><DataTable v-if="selectedTenantId" :columns="trafficColumns" :rows="traffic.ledger || []" :loading="loading" empty-text="暂无流量流水" /></section>
    </template>

    <template v-else-if="tab === 'storage'">
      <section class="platform-panel"><div class="platform-panel-head"><div><h3>租户存储计费</h3><p>按租户实际占用存储计费，单价单位为 CNY / GB·月；用量由存储适配器同步</p></div><select v-model.number="selectedTenantId" @change="loadStorage"><option :value="0">请选择客户租户</option><option v-for="tenant in tenants" :key="tenant.id" :value="tenant.id">{{ tenant.tenant_name }} · {{ tenant.tenant_code }}</option></select><button class="button button-primary" :disabled="!selectedTenantId" @click="openStorageModal">配置存储计费</button></div><div v-if="selectedTenantId && storage.quota_bytes !== undefined" class="traffic-account"><div class="account-summary storage-summary"><div><span>配额总量</span><b>{{ trafficSize(storage.quota_bytes) }}</b></div><div><span>已使用</span><b>{{ trafficSize(storage.used_bytes) }}</b></div><div><span>剩余存储</span><b :class="storage.exhausted ? 'text-danger' : ''">{{ trafficSize(storage.remaining_bytes) }}</b></div><div><span>预计月费</span><b>¥ {{ money(storage.estimated_monthly_charge) }}</b><small>¥ {{ money(storage.unit_price_per_gb_month) }} / GB·月</small></div></div><div class="traffic-progress"><div><span>使用进度</span><b>{{ percentage(storage.used_percent) }}%</b></div><div class="progress"><i :class="{ danger: storage.exhausted, warning: storage.low_balance }" :style="{ width: `${Math.min(100, Number(storage.used_percent || 0))}%` }"></i></div><small>{{ storage.exhausted ? '存储配额已用尽，继续写入前请扩容' : `剩余低于 ${storage.warning_threshold_percent}% 时提醒` }}</small></div></div><div v-else class="platform-empty">请先选择一个客户租户</div><DataTable v-if="selectedTenantId" :columns="storageColumns" :rows="storage.ledger || []" :loading="loading" empty-text="暂无存储流水" /></section>
    </template>

    <template v-else-if="tab === 'tickets'">
      <section class="platform-panel"><div class="platform-panel-head"><div><h3>在线答疑 / 客服</h3><p>统一受理客户问题、分派跟进并在线回复</p></div><div class="platform-head-actions"><select v-model="ticketStatus" @change="loadTickets"><option value="">全部状态</option><option value="OPEN">待处理</option><option value="IN_PROGRESS">处理中</option><option value="WAITING_CUSTOMER">待客户回复</option><option value="CLOSED">已关闭</option></select><button class="button button-primary" @click="openTicketCreate">新建工单</button></div></div><DataTable :columns="ticketColumns" :rows="tickets" :loading="loading"><template #cell-status="{ value }"><span class="status-pill" :class="`status-${String(value).toLowerCase()}`">{{ ticketStatusLabel(value) }}</span></template><template #actions="{ row }"><button class="table-action" @click="openTicketReply(row)">查看 / 回复</button></template></DataTable></section>
    </template>

    <template v-else-if="tab === 'training'">
      <section class="platform-panel"><div class="platform-panel-head"><div><h3>培训管理</h3><p>发布产品培训课程并为客户租户登记报名</p></div><button class="button button-primary" @click="openCourseCreate">新建课程</button></div><DataTable :columns="courseColumns" :rows="courses" :loading="loading"><template #cell-status="{ value }"><span class="status-pill" :class="`status-${String(value).toLowerCase()}`">{{ value }}</span></template><template #actions="{ row }"><div class="inline-actions"><button class="table-action" @click="openCourseEdit(row)">编辑</button><button class="table-action" @click="openEnroll(row)">登记报名</button></div></template></DataTable></section>
    </template>

    <template v-else-if="tab === 'marketing'">
      <section class="platform-panel"><div class="platform-panel-head"><div><h3>营销活动</h3><p>面向客户租户管理公告、活动和产品增长触达</p></div><button class="button button-primary" @click="openCampaignCreate">新建活动</button></div><DataTable :columns="campaignColumns" :rows="campaigns" :loading="loading"><template #cell-status="{ value }"><span class="status-pill" :class="`status-${String(value).toLowerCase()}`">{{ value }}</span></template><template #actions="{ row }"><button class="table-action" @click="openCampaignEdit(row)">编辑</button></template></DataTable></section>
    </template>

    <AppModal v-model="showTenantModal" :title="editingTenant ? '编辑客户租户' : '新增客户租户'" subtitle="客户租户与平台总管理员租户相互隔离" :loading="saving" confirm-text="保存租户" @confirm="saveTenant"><DynamicForm v-model="tenantForm" :schema="tenantSchema" :columns="2" /></AppModal>
    <AppModal v-model="showBillingModal" title="新增计费记录" subtitle="消费会扣减账户余额，充值和退款会增加余额" :loading="saving" confirm-text="保存记账" @confirm="saveBilling"><DynamicForm v-model="billingForm" :schema="billingSchema" :columns="2" /></AppModal>
    <AppModal v-model="showPointsModal" title="调整租户积分" subtitle="扣减积分时余额不能低于 0" :loading="saving" confirm-text="保存调整" @confirm="savePoints"><DynamicForm v-model="pointsForm" :schema="pointsSchema" /></AppModal>
    <AppModal v-model="showTrafficModal" title="分配租户流量" subtitle="流量按请求体与响应体的实际字节数扣减；配额可增加或保持不变，不能小于已使用量" :loading="saving" confirm-text="保存流量配额" @confirm="saveTraffic"><DynamicForm v-model="trafficForm" :schema="trafficSchema" :columns="2" /></AppModal>
    <AppModal v-model="showStorageModal" title="配置租户存储计费" subtitle="存储按实际占用量与 GB·月单价计算预计月费；配额不能小于已使用量" :loading="saving" confirm-text="保存存储配置" @confirm="saveStorage"><DynamicForm v-model="storageForm" :schema="storageSchema" :columns="2" /></AppModal>
    <AppModal v-model="showTicketModal" :title="editingTicket ? `工单 #${editingTicket.id}` : '新建客服工单'" :subtitle="editingTicket ? `${editingTicket.tenant_name} · ${editingTicket.subject}` : '创建后可继续在线回复'" :loading="saving" :confirm-text="editingTicket ? '发送回复' : '创建工单'" @confirm="saveTicket"><div v-if="editingTicket" class="ticket-thread"><div v-for="message in ticketMessages" :key="message.id" :class="['ticket-message', message.sender_type === 'PLATFORM' ? 'from-platform' : '']"><b>{{ message.sender_name }}</b><p>{{ message.content }}</p><small>{{ formatDate(message.created_at) }}</small></div><p v-if="!ticketMessages.length" class="platform-empty">暂无消息</p></div><DynamicForm v-model="ticketForm" :schema="editingTicket ? replyTicketSchema : ticketSchema" /></AppModal>
    <AppModal v-model="showCourseModal" :title="editingCourse ? '编辑培训课程' : '新建培训课程'" :loading="saving" confirm-text="保存课程" @confirm="saveCourse"><DynamicForm v-model="courseForm" :schema="courseSchema" :columns="2" /></AppModal>
    <AppModal v-model="showEnrollModal" title="登记培训报名" subtitle="将客户租户加入当前课程" :loading="saving" confirm-text="确认报名" @confirm="saveEnrollment"><DynamicForm v-model="enrollForm" :schema="enrollSchema" /></AppModal>
    <AppModal v-model="showCampaignModal" :title="editingCampaign ? '编辑营销活动' : '新建营销活动'" :loading="saving" confirm-text="保存活动" @confirm="saveCampaign"><DynamicForm v-model="campaignForm" :schema="campaignSchema" :columns="2" /></AppModal>
  </PageShell>
</template>

<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import PageShell from '../components/PageShell.vue'
import DataTable from '../components/DataTable.vue'
import AppModal from '../components/AppModal.vue'
import DynamicForm from '../components/DynamicForm.vue'
import { request } from '../api'

const route = useRoute(); const router = useRouter()
const tab = ref(route.params.tab || 'overview'); const loading = ref(false); const saving = ref(false); const notice = ref(null)
const tabs = [{ key: 'overview', label: '平台总览' }, { key: 'tenants', label: '租户维护' }, { key: 'features', label: '功能授权' }, { key: 'traffic', label: '流量管理' }, { key: 'storage', label: '存储计费' }, { key: 'billing', label: '计费' }, { key: 'points', label: '积分' }, { key: 'tickets', label: '在线答疑 / 客服' }, { key: 'training', label: '培训' }, { key: 'marketing', label: '营销' }]
const overview = ref({}); const tenants = ref([]); const features = ref([]); const featureRows = ref([]); const selectedFeatureCodes = ref([]); const selectedTenantId = ref(0); const tenantKeyword = ref(''); const ticketStatus = ref('')
const billing = ref({}); const points = ref({}); const traffic = ref({}); const storage = ref({}); const tickets = ref([]); const ticketMessages = ref([]); const courses = ref([]); const campaigns = ref([])
const editingTenant = ref(null); const editingTicket = ref(null); const editingCourse = ref(null); const editingCampaign = ref(null); const currentCourseId = ref(0)
const showTenantModal = ref(false); const showBillingModal = ref(false); const showPointsModal = ref(false); const showTrafficModal = ref(false); const showStorageModal = ref(false); const showTicketModal = ref(false); const showCourseModal = ref(false); const showEnrollModal = ref(false); const showCampaignModal = ref(false)
const tenantForm = ref({}); const billingForm = ref({}); const pointsForm = ref({}); const trafficForm = ref({}); const storageForm = ref({}); const ticketForm = ref({}); const courseForm = ref({}); const enrollForm = ref({}); const campaignForm = ref({})
const overviewCards = [{ key: 'customerTenants', label: '客户租户', hint: '已创建的客户工作区' }, { key: 'activeTenants', label: '活跃租户', hint: '当前可正常登录' }, { key: 'openTickets', label: '待处理工单', hint: '客服与在线答疑' }, { key: 'billingTotal', label: '累计收款', hint: '平台计费账户汇总' }]
const capabilityCards = [{ icon: '01', label: '租户生命周期', description: '创建、停用、套餐维护' }, { icon: '02', label: '产品功能授权', description: '按租户控制模块和接口' }, { icon: '03', label: '商业化运营', description: '计费、积分与营销活动' }, { icon: '04', label: '客户成功', description: '答疑、客服与培训' }]
const quickActions = [{ key: 'tenants', icon: '⌂', label: '租户维护', description: '查看客户工作区' }, { key: 'features', icon: '◇', label: '功能授权', description: '配置产品模块权限' }, { key: 'traffic', icon: '↯', label: '流量管理', description: '分配额度与查看消耗' }, { key: 'storage', icon: '▤', label: '存储计费', description: '配置存储配额与单价' }, { key: 'billing', icon: '¥', label: '计费中心', description: '充值与消费流水' }, { key: 'tickets', icon: '?', label: '客户服务', description: '在线回复客户问题' }, { key: 'training', icon: '▣', label: '培训中心', description: '安排产品培训' }, { key: 'marketing', icon: '↗', label: '营销活动', description: '发布平台活动' }]
const tenantColumns = [{ key: 'tenant_name', label: '租户名称' }, { key: 'tenant_code', label: '编码' }, { key: 'plan_code', label: '套餐' }, { key: 'user_count', label: '用户数', format: (v, row) => `${v || 0} / ${row.max_users}` }, { key: 'feature_count', label: '已授权功能' }, { key: 'traffic_remaining_bytes', label: '剩余流量' }, { key: 'storage_remaining_bytes', label: '剩余存储', format: trafficSize }, { key: 'balance', label: '账户余额', format: v => `¥ ${money(v)}` }, { key: 'points', label: '积分' }, { key: 'status', label: '状态' }]
const billingColumns = [{ key: 'created_at', label: '时间', format: formatDate }, { key: 'record_type', label: '类型', format: value => value === 'STORAGE' ? '存储计费' : value }, { key: 'amount', label: '金额', format: v => `¥ ${money(v)}` }, { key: 'description', label: '说明' }, { key: 'status', label: '状态' }, { key: 'created_by', label: '操作人' }]
const pointsColumns = [{ key: 'created_at', label: '时间', format: formatDate }, { key: 'change_amount', label: '变动', format: v => Number(v) > 0 ? `+${v}` : v }, { key: 'balance_after', label: '变动后余额' }, { key: 'reason', label: '原因' }, { key: 'created_by', label: '操作人' }]
const trafficColumns = [{ key: 'created_at', label: '时间', format: formatDate }, { key: 'action_type', label: '动作', format: value => value === 'CONSUME' ? '实际消耗' : '分配配额' }, { key: 'consumed_bytes', label: '消耗流量', format: trafficSize }, { key: 'change_bytes', label: '配额变动', format: value => Number(value) > 0 ? `+${trafficSize(value)}` : trafficSize(value) }, { key: 'quota_after_bytes', label: '配额总量', format: trafficSize }, { key: 'used_after_bytes', label: '已使用', format: trafficSize }, { key: 'description', label: '说明' }, { key: 'created_by', label: '操作人' }]
const storageColumns = [{ key: 'created_at', label: '时间', format: formatDate }, { key: 'action_type', label: '动作', format: value => ({ ALLOCATE: '调整配额', CONSUME: '存储增加', RELEASE: '存储释放' }[value] || value) }, { key: 'change_bytes', label: '用量变动', format: value => Number(value) > 0 ? `+${trafficSize(value)}` : trafficSize(value) }, { key: 'consumed_bytes', label: '计费增量', format: trafficSize }, { key: 'quota_after_bytes', label: '配额总量', format: trafficSize }, { key: 'used_after_bytes', label: '已使用', format: trafficSize }, { key: 'description', label: '说明' }, { key: 'created_by', label: '操作人' }]
const ticketColumns = [{ key: 'tenant_name', label: '客户租户' }, { key: 'category', label: '类型' }, { key: 'subject', label: '主题' }, { key: 'priority', label: '优先级' }, { key: 'status', label: '状态' }, { key: 'message_count', label: '消息数' }, { key: 'updated_at', label: '最近更新', format: formatDate }]
const courseColumns = [{ key: 'course_name', label: '课程名称' }, { key: 'course_code', label: '编码' }, { key: 'category', label: '分类' }, { key: 'instructor', label: '讲师' }, { key: 'schedule_at', label: '开课时间', format: formatDate }, { key: 'enrollment_count', label: '报名数' }, { key: 'status', label: '状态' }]
const campaignColumns = [{ key: 'campaign_name', label: '活动名称' }, { key: 'campaign_code', label: '编码' }, { key: 'campaign_type', label: '类型' }, { key: 'audience', label: '触达范围' }, { key: 'starts_at', label: '开始时间', format: formatDate }, { key: 'status', label: '状态' }]
const tenantSchema = computed(() => editingTenant.value ? [{ key: 'tenantName', label: '企业名称', required: true }, { key: 'planCode', label: '套餐', required: true }, { key: 'contactName', label: '联系人' }, { key: 'contactEmail', label: '联系邮箱' }, { key: 'maxUsers', label: '用户上限', type: 'number' }, { key: 'status', label: '状态', type: 'select', options: [{ value: 1, label: '已启用' }, { value: 0, label: '已停用' }] }] : [{ key: 'tenantName', label: '企业名称', required: true }, { key: 'tenantCode', label: '工作区编码', required: true }, { key: 'displayName', label: '管理员姓名', required: true }, { key: 'username', label: '管理员账号', required: true }, { key: 'password', label: '初始密码', type: 'password', required: true }, { key: 'contactEmail', label: '联系邮箱' }, { key: 'planCode', label: '套餐' }, { key: 'maxUsers', label: '用户上限', type: 'number' }])
const billingSchema = [{ key: 'recordType', label: '计费类型', type: 'select', options: [{ value: 'PAYMENT', label: '充值 / 收款' }, { value: 'CHARGE', label: '消费' }, { value: 'STORAGE', label: '存储计费' }, { value: 'REFUND', label: '退款' }, { value: 'ADJUSTMENT', label: '余额调整' }] }, { key: 'amount', label: '金额', type: 'number', required: true }, { key: 'description', label: '计费说明', required: true }, { key: 'periodStart', label: '周期开始' }, { key: 'periodEnd', label: '周期结束' }]
const pointsSchema = [{ key: 'amount', label: '积分变动', type: 'number', required: true }, { key: 'reason', label: '变动原因', required: true }, { key: 'referenceType', label: '关联类型' }, { key: 'referenceId', label: '关联编号' }]
const trafficSchema = [{ key: 'quotaGb', label: '流量配额（GB）', type: 'number', required: true }, { key: 'warningThresholdPercent', label: '低余额预警（%）', type: 'number', required: true }, { key: 'reason', label: '分配说明', required: true }]
const storageSchema = [{ key: 'quotaGb', label: '存储配额（GB）', type: 'number', required: true }, { key: 'unitPricePerGbMonth', label: '存储单价（¥ / GB·月）', type: 'number', required: true }, { key: 'warningThresholdPercent', label: '低余额预警（%）', type: 'number', required: true }, { key: 'reason', label: '配置说明', required: true }]
const ticketSchema = computed(() => [{ key: 'tenantId', label: '客户租户', type: 'select', options: tenants.value.map(item => ({ value: item.id, label: `${item.tenant_name} · ${item.tenant_code}` })), required: true }, { key: 'category', label: '类型', type: 'select', options: [{ value: 'QUESTION', label: '产品答疑' }, { value: 'SERVICE', label: '客服服务' }, { value: 'INCIDENT', label: '故障支持' }] }, { key: 'priority', label: '优先级', type: 'select', options: [{ value: 'NORMAL', label: '普通' }, { value: 'HIGH', label: '高' }, { value: 'URGENT', label: '紧急' }] }, { key: 'subject', label: '问题主题', required: true }, { key: 'content', label: '问题内容', type: 'textarea', required: true }])
const replyTicketSchema = [{ key: 'content', label: '回复内容', type: 'textarea', required: true }, { key: 'status', label: '回复后状态', type: 'select', options: [{ value: 'WAITING_CUSTOMER', label: '待客户回复' }, { value: 'IN_PROGRESS', label: '继续跟进' }, { value: 'CLOSED', label: '关闭工单' }] }]
const courseSchema = [{ key: 'courseCode', label: '课程编码', required: true }, { key: 'courseName', label: '课程名称', required: true }, { key: 'category', label: '分类' }, { key: 'instructor', label: '讲师' }, { key: 'scheduleAt', label: '开课时间' }, { key: 'capacity', label: '人数上限', type: 'number' }, { key: 'status', label: '状态', type: 'select', options: [{ value: 'DRAFT', label: '草稿' }, { value: 'PUBLISHED', label: '已发布' }, { value: 'ENDED', label: '已结束' }] }, { key: 'description', label: '课程说明', type: 'textarea' }]
const enrollSchema = computed(() => [{ key: 'tenantId', label: '客户租户', type: 'select', options: tenants.value.map(item => ({ value: item.id, label: `${item.tenant_name} · ${item.tenant_code}` })), required: true }, { key: 'contactName', label: '参训联系人' }])
const campaignSchema = [{ key: 'campaignCode', label: '活动编码', required: true }, { key: 'campaignName', label: '活动名称', required: true }, { key: 'campaignType', label: '活动类型' }, { key: 'audience', label: '触达范围' }, { key: 'status', label: '状态', type: 'select', options: [{ value: 'DRAFT', label: '草稿' }, { value: 'SCHEDULED', label: '待发布' }, { value: 'RUNNING', label: '进行中' }, { value: 'ENDED', label: '已结束' }] }, { key: 'startsAt', label: '开始时间' }, { key: 'endsAt', label: '结束时间' }, { key: 'content', label: '活动内容', type: 'textarea', required: true }]

function formatNumber(value) { return Number(value || 0).toLocaleString('zh-CN') }; function money(value) { return Number(value || 0).toFixed(2) }; function formatDate(value) { return value ? String(value).replace('T', ' ').slice(0, 16) : '-' }; function trafficSize(value) { const bytes = Number(value || 0); if (bytes >= 1024 ** 3) return `${(bytes / 1024 ** 3).toFixed(2)} GB`; if (bytes >= 1024 ** 2) return `${(bytes / 1024 ** 2).toFixed(2)} MB`; if (bytes >= 1024) return `${(bytes / 1024).toFixed(2)} KB`; return `${Math.round(bytes)} B` }; function percentage(value) { return Number(value || 0).toFixed(1) }; function showNotice(message, type = 'success') { notice.value = { message, type }; window.clearTimeout(showNotice.timer); showNotice.timer = window.setTimeout(() => notice.value = null, 3600) }
function switchTab(value) { tab.value = value; router.push(`/platform/${value}`); load() }
function ticketStatusLabel(value) { return ({ OPEN: '待处理', IN_PROGRESS: '处理中', WAITING_CUSTOMER: '待客户回复', CLOSED: '已关闭' }[value] || value) }
async function load() { loading.value = true; try { overview.value = await request('/platform/overview'); if (tab.value === 'overview') return; if (!tenants.value.length || tab.value === 'tenants' || tab.value === 'features' || tab.value === 'traffic' || tab.value === 'storage' || tab.value === 'billing' || tab.value === 'points' || tab.value === 'tickets' || tab.value === 'training') tenants.value = await request(`/platform/tenants?keyword=${encodeURIComponent(tenantKeyword.value)}`) || []; if (tab.value === 'tenants') return; if (tab.value === 'features') { features.value = await request('/platform/features') || []; if (selectedTenantId.value) await loadFeatureEditor(); return }; if (tab.value === 'traffic') return await loadTraffic(); if (tab.value === 'storage') return await loadStorage(); if (tab.value === 'billing') return await loadBilling(); if (tab.value === 'points') return await loadPoints(); if (tab.value === 'tickets') return await loadTickets(); if (tab.value === 'training') return courses.value = await request('/platform/training/courses') || []; if (tab.value === 'marketing') campaigns.value = await request('/platform/campaigns') || [] } catch (error) { showNotice(error.message, 'error') } finally { loading.value = false } }
async function loadTenants() { try { tenants.value = await request(`/platform/tenants?keyword=${encodeURIComponent(tenantKeyword.value)}`) || [] } catch (error) { showNotice(error.message, 'error') } }
async function loadFeatureEditor() { if (!selectedTenantId.value) { featureRows.value = []; selectedFeatureCodes.value = []; return }; featureRows.value = await request(`/platform/tenants/${selectedTenantId.value}/features`) || []; selectedFeatureCodes.value = featureRows.value.filter(item => Number(item.granted_status) === 1).map(item => item.feature_code) }
async function loadBilling() { if (!selectedTenantId.value) return; billing.value = await request(`/platform/billing?tenantId=${selectedTenantId.value}`) || {} }
async function loadPoints() { if (!selectedTenantId.value) return; points.value = await request(`/platform/points?tenantId=${selectedTenantId.value}`) || {} }
async function loadTraffic() { if (!selectedTenantId.value) { traffic.value = {}; return }; traffic.value = await request(`/platform/traffic?tenantId=${selectedTenantId.value}`) || {} }
async function loadStorage() { if (!selectedTenantId.value) { storage.value = {}; return }; storage.value = await request(`/platform/storage?tenantId=${selectedTenantId.value}`) || {} }
async function loadTickets() { tickets.value = await request(`/platform/tickets${ticketStatus.value ? `?status=${ticketStatus.value}` : ''}`) || [] }
function openTenantCreate() { editingTenant.value = null; tenantForm.value = { tenantName: '', tenantCode: '', displayName: '', username: '', password: '', planCode: 'STARTER', maxUsers: 10 }; showTenantModal.value = true }
function openTenantEdit(row) { editingTenant.value = row; tenantForm.value = { tenantName: row.tenant_name, planCode: row.plan_code, contactName: row.contact_name || '', contactEmail: row.contact_email || '', maxUsers: Number(row.max_users || 10), status: Number(row.status) }; showTenantModal.value = true }
function openFeature(row) { selectedTenantId.value = row.id; switchTab('features') }
function openBilling(row) { selectedTenantId.value = row.id; switchTab('billing') }
function openPoints(row) { selectedTenantId.value = row.id; switchTab('points') }
function openTraffic(row) { selectedTenantId.value = row.id; switchTab('traffic') }
function openStorage(row) { selectedTenantId.value = row.id; switchTab('storage') }
async function saveTenant() { if (!editingTenant.value && (tenantForm.value.password || '').length < 8) return showNotice('初始密码至少需要 8 位', 'warning'); await saveRequest(editingTenant.value ? `/platform/tenants/${editingTenant.value.id}` : '/platform/tenants', editingTenant.value ? 'PUT' : 'POST', tenantForm.value, '租户已保存', showTenantModal, load) }
async function saveFeatures() { const grants = features.value.map(feature => ({ featureCode: feature.feature_code, status: selectedFeatureCodes.value.includes(feature.feature_code) ? 1 : 0, quotaJson: '{}' })); await saveRequest(`/platform/tenants/${selectedTenantId.value}/features`, 'PUT', grants, '功能授权已保存', null, loadFeatureEditor) }
function openBillingModal() { billingForm.value = { recordType: 'PAYMENT', amount: '', description: '', periodStart: '', periodEnd: '' }; showBillingModal.value = true }
async function saveBilling() { await saveRequest('/platform/billing/records', 'POST', { ...billingForm.value, tenantId: selectedTenantId.value }, '计费记录已保存', showBillingModal, loadBilling) }
function openPointsModal() { pointsForm.value = { amount: '', reason: '', referenceType: '', referenceId: '' }; showPointsModal.value = true }
async function savePoints() { await saveRequest('/platform/points/adjust', 'POST', { ...pointsForm.value, tenantId: selectedTenantId.value }, '积分已调整', showPointsModal, loadPoints) }
function openTrafficModal() { trafficForm.value = { quotaGb: traffic.value.quota_bytes ? (Number(traffic.value.quota_bytes) / 1024 ** 3).toFixed(2) : '', warningThresholdPercent: Number(traffic.value.warning_threshold_percent ?? 10), reason: '' }; showTrafficModal.value = true }
async function saveTraffic() { const quotaGb = Number(trafficForm.value.quotaGb); if (!Number.isFinite(quotaGb) || quotaGb < 0) return showNotice('流量配额必须是大于等于 0 的数字', 'warning'); await saveRequest('/platform/traffic', 'PUT', { tenantId: selectedTenantId.value, quotaBytes: Math.round(quotaGb * 1024 ** 3), warningThresholdPercent: Number(trafficForm.value.warningThresholdPercent), reason: trafficForm.value.reason }, '租户流量配额已保存', showTrafficModal, loadTraffic) }
function openStorageModal() { storageForm.value = { quotaGb: storage.quota_bytes ? (Number(storage.quota_bytes) / 1024 ** 3).toFixed(2) : '', unitPricePerGbMonth: Number(storage.unit_price_per_gb_month ?? 0).toFixed(4), warningThresholdPercent: Number(storage.warning_threshold_percent ?? 10), reason: '' }; showStorageModal.value = true }
async function saveStorage() { const quotaGb = Number(storageForm.value.quotaGb); const unitPrice = Number(storageForm.value.unitPricePerGbMonth); if (!Number.isFinite(quotaGb) || quotaGb < 0) return showNotice('存储配额必须是大于等于 0 的数字', 'warning'); if (!Number.isFinite(unitPrice) || unitPrice < 0) return showNotice('存储单价必须是大于等于 0 的数字', 'warning'); await saveRequest('/platform/storage', 'PUT', { tenantId: selectedTenantId.value, quotaBytes: Math.round(quotaGb * 1024 ** 3), unitPricePerGbMonth: unitPrice, warningThresholdPercent: Number(storageForm.value.warningThresholdPercent), reason: storageForm.value.reason }, '租户存储计费配置已保存', showStorageModal, loadStorage) }
function openTicketCreate() { editingTicket.value = null; ticketForm.value = { tenantId: tenants.value[0]?.id || 0, category: 'QUESTION', priority: 'NORMAL', subject: '', content: '' }; showTicketModal.value = true }
async function openTicketReply(row) { editingTicket.value = row; ticketMessages.value = await request(`/platform/tickets/${row.id}/messages`) || []; ticketForm.value = { content: '', status: 'WAITING_CUSTOMER' }; showTicketModal.value = true }
async function saveTicket() { if (editingTicket.value) { await saveRequest(`/platform/tickets/${editingTicket.value.id}/reply`, 'POST', ticketForm.value, '回复已发送', showTicketModal, loadTickets) } else { await saveRequest('/platform/tickets', 'POST', ticketForm.value, '工单已创建', showTicketModal, loadTickets) } }
function openCourseCreate() { editingCourse.value = null; courseForm.value = { courseCode: '', courseName: '', category: 'PRODUCT', instructor: '', scheduleAt: '', capacity: 30, status: 'DRAFT', description: '' }; showCourseModal.value = true }
function openCourseEdit(row) { editingCourse.value = row; courseForm.value = { courseCode: row.course_code, courseName: row.course_name, category: row.category, instructor: row.instructor || '', scheduleAt: row.schedule_at || '', capacity: Number(row.capacity || 0), status: row.status, description: row.description || '' }; showCourseModal.value = true }
async function saveCourse() { await saveRequest(editingCourse.value ? `/platform/training/courses/${editingCourse.value.id}` : '/platform/training/courses', editingCourse.value ? 'PUT' : 'POST', courseForm.value, '课程已保存', showCourseModal, load) }
function openEnroll(row) { currentCourseId.value = row.id; enrollForm.value = { tenantId: tenants.value[0]?.id || 0, contactName: '' }; showEnrollModal.value = true }
async function saveEnrollment() { await saveRequest(`/platform/training/courses/${currentCourseId.value}/enroll`, 'POST', enrollForm.value, '培训报名已登记', showEnrollModal, load) }
function openCampaignCreate() { editingCampaign.value = null; campaignForm.value = { campaignCode: '', campaignName: '', campaignType: 'ANNOUNCEMENT', audience: 'ALL_CUSTOMERS', status: 'DRAFT', startsAt: '', endsAt: '', content: '' }; showCampaignModal.value = true }
function openCampaignEdit(row) { editingCampaign.value = row; campaignForm.value = { campaignCode: row.campaign_code, campaignName: row.campaign_name, campaignType: row.campaign_type, audience: row.audience, status: row.status, startsAt: row.starts_at || '', endsAt: row.ends_at || '', content: row.content || '' }; showCampaignModal.value = true }
async function saveCampaign() { await saveRequest(editingCampaign.value ? `/platform/campaigns/${editingCampaign.value.id}` : '/platform/campaigns', editingCampaign.value ? 'PUT' : 'POST', campaignForm.value, '营销活动已保存', showCampaignModal, load) }
async function saveRequest(path, method, body, message, modal, after) { saving.value = true; try { await request(path, { method, body: JSON.stringify(body) }); if (modal) modal.value = false; showNotice(message); if (after) await after() } catch (error) { showNotice(error.message, 'error') } finally { saving.value = false } }
watch(() => route.params.tab, value => { const next = value || 'overview'; if (tab.value !== next) { tab.value = next; load() } }); onMounted(load)
</script>

